# Model definition
def create_model(input_shape, num_classes):
    model = models.Sequential([
        layers.Conv2D(32, (3, 3), activation='relu', input_shape=input_shape),
        layers.MaxPooling2D((2, 2)),
        layers.Conv2D(64, (3, 3), activation='relu'),
        layers.MaxPooling2D((2, 2)),
        layers.Flatten(),
        layers.Dense(128, activation='relu'),
        layers.Dropout(0.5),
        layers.Dense(num_classes, activation='sigmoid')  # Sigmoid for multi-label classification
    ])
    
    model.compile(optimizer='adam',
                  loss='binary_crossentropy',  # Binary cross-entropy for multi-label classification
                  metrics=['AUC'])  # AUC is a suitable metric for multi-label classification
    
    return model

# Training loop
def train_model(model, X_train, y_train, X_val, y_val):
    early_stopping = EarlyStopping(monitor='val_auc', patience=5, restore_best_weights=True)
    
    history = model.fit(
        X_train,
        y_train,
        epochs=100,
        batch_size=32,
        validation_data=(X_val, y_val),
        callbacks=[early_stopping],
        verbose=1
    )
    
    return history

# Evaluation function
def evaluate_model(model, X_val, y_val):
    results = model.evaluate(X_val, y_val, verbose=0)
    print(f"Validation Loss: {results[0]}, Validation AUC: {results[1]}")

